public class CrossoverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("cross(\"AAAA\", \"BBBB\", 2)", "AABB", Crossover.cross("AAAA", "BBBB", 2));
        check("cross(\"abcdef\", \"uvwxyz\", 3)", "abcxyz", Crossover.cross("abcdef", "uvwxyz", 3));
        check("cut 0 gives all of b", "BBBB", Crossover.cross("AAAA", "BBBB", 0));
        check("cut == length gives all of a", "AAAA", Crossover.cross("AAAA", "BBBB", 4));
        check("oversized cut is clamped", "AAAA", Crossover.cross("AAAA", "BBBB", 9));
        check("negative cut is clamped", "BBBB", Crossover.cross("AAAA", "BBBB", -2));
        check("cross(\"10101\", \"01010\", 2)", "10010", Crossover.cross("10101", "01010", 2));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

